import csv,glob,os,re
log={int(r['run_id']):r for r in csv.DictReader(open('data/run_log.csv'))}
def nu(T):
    mu=2.414e-5*10**(247.8/(T+273.15-140))
    rho=999.974950*(1-(T-3.983035)**2*(T+301.797)/(522528.9*(T+69.34881)))
    return mu/rho
app={}
for line in open('paper/draft.md'):
    m=re.match(r'\| (\d+)†? \| [\d.]+ \| [\d.]+ \| [\d.]+ \| ([\d ]+) \|',line)
