    Re=U*D/nu(T); Re20=U*D/1.004e-6
    flag='' if abs(Re-app[k])<=1 else ' MISMATCH'
    print(k,T,round(Re),app[k],round(Re20),flag)
# run 17 zero check
def load(f):
    L=open(f).read().splitlines()
    if ';' in L[0]:
        rows=[l.split(';') for l in L[1:] if l]
    else:
        rows=[l.split(',') for l in L if l and not l.startswith('#')][1:]
    return [(float(a),float(b)) for a,b in rows]
for f in sorted(glob.glob('data/raw/*/run_*.csv')):
    run=int(os.path.basename(f)[4:7]); s=0.02129 if '/2026-' in f else 0.02001
    d=load(f); tmax=d[-1][0]
    v0=[v for t,v in d if t<1]; v0=sum(v0)/len(v0)
    ve=[v for t,v in d if t>tmax-1]; ve=sum(ve)/len(ve)
    if run in (16,17,18): print(run,'end-zero N',round((ve-v0)/s,4))
